/* Premium Styling for Qualitative Text Card Custom Visual */
/* Base Viewport Container */
.text-viz-root {
  width: 100%;
  height: 100%;
  position: relative;
  box-sizing: border-box;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  padding: 8px 16px 8px 8px;
  /* CSS Custom Properties bound dynamically in visual.ts */
  --accent-color: #3b82f6;
  --bg-color: #ffffff;
  --text-color: #1e293b;
  --font-family: 'Segoe UI', sans-serif;
  --title-size: 16px;
  --body-size: 13px;
  --card-padding: 18px;
  --grid-gap: 16px;
  font-family: var(--font-family);
  color: var(--text-color);
}
.text-viz-root::-webkit-scrollbar {
  width: 6px;
}
.text-viz-root::-webkit-scrollbar-thumb {
  background-color: rgba(148, 163, 184, 0.3);
  border-radius: 4px;
}
/* --------------------------------------------------- */
/* LAYOUTS */
/* --------------------------------------------------- */
/* Layout A: Strict Card Grid */
.text-grid-container {
  display: grid;
  gap: var(--grid-gap);
  width: 100%;
}
.text-grid-cols-1 {
  grid-template-columns: 1fr;
}
.text-grid-cols-2 {
  grid-template-columns: repeat(2, 1fr);
}
.text-grid-cols-3 {
  grid-template-columns: repeat(3, 1fr);
}
/* Layout B: Vertical Timeline Feed */
.text-timeline-container {
  position: relative;
  padding-left: 28px;
  display: flex;
  flex-direction: column;
  gap: var(--grid-gap);
  width: 100%;
}
.text-timeline-stem {
  position: absolute;
  left: 10px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background-color: var(--accent-color);
  opacity: 0.3;
  z-index: 1;
}
/* Layout C: Master-Detail Split Screen */
.text-detail-container {
  display: flex;
  gap: var(--grid-gap);
  width: 100%;
  height: 100%;
  min-height: 400px;
  overflow: hidden;
}
.detail-list-pane {
  flex: 2;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow-y: auto;
  padding-right: 6px;
  max-height: 100%;
}
.detail-view-pane {
  flex: 3;
  border-radius: 12px;
  padding: 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
  border: 1px solid rgba(0, 0, 0, 0.08);
  background-color: rgba(255, 255, 255, 0.5);
  box-shadow: 0 4px 12px -2px rgba(0, 0, 0, 0.03);
  max-height: 100%;
  position: relative;
}
.text-viz-root.theme-dark-bg .detail-view-pane {
  border-color: rgba(255, 255, 255, 0.08);
  background-color: rgba(30, 41, 59, 0.5);
}
/* --------------------------------------------------- */
/* CARD AESTHETICS & THEMES */
/* --------------------------------------------------- */
.text-card {
  border-radius: 12px;
  padding: var(--card-padding);
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.2s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.2s;
  box-sizing: border-box;
  overflow: hidden;
}
/* Theme 1: Premium Glassmorphic Card */
.theme-glassmorphic {
  background-color: rgba(var(--bg-color-rgb, 255, 255, 255), 0.65);
  border: 1px solid rgba(var(--bg-color-rgb, 255, 255, 255), 0.4);
  box-shadow: 0 4px 20px -2px rgba(148, 163, 184, 0.12), 0 2px 8px -1px rgba(148, 163, 184, 0.06);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.text-viz-root.theme-dark-bg .theme-glassmorphic {
  background-color: rgba(var(--bg-color-rgb, 30, 41, 59), 0.65);
  border-color: rgba(var(--bg-color-rgb, 255, 255, 255), 0.07);
  box-shadow: 0 4px 20px -2px rgba(0, 0, 0, 0.25);
}
/* Theme 2: High-Contrast Solid Card */
.theme-solid {
  background-color: var(--bg-color);
  border: 1.5px solid rgba(0, 0, 0, 0.08);
  box-shadow: 0 4px 10px -1px rgba(0, 0, 0, 0.04);
}
.text-viz-root.theme-dark-bg .theme-solid {
  border-color: rgba(255, 255, 255, 0.12);
}
/* Theme 3: Minimalist Flat Card */
.theme-flat {
  background-color: transparent;
  border: 1px solid rgba(0, 0, 0, 0.08);
  box-shadow: none;
}
.text-viz-root.theme-dark-bg .theme-flat {
  border-color: rgba(255, 255, 255, 0.1);
}
/* Hover Elevations */
.text-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px -4px rgba(148, 163, 184, 0.25);
}
.text-viz-root.theme-dark-bg .text-card:hover {
  box-shadow: 0 8px 24px -4px rgba(0, 0, 0, 0.4);
}
/* Selection / Filtering State */
.text-card.selected-card {
  border-color: var(--accent-color) !important;
  border-width: 2px !important;
  transform: scale(1.01) translateY(-1px);
  box-shadow: 0 6px 20px -2px rgba(59, 130, 246, 0.15) !important;
}
/* Timeline Specific Node Dots */
.timeline-node {
  position: absolute;
  left: -22px;
  top: 24px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--bg-color);
  border: 2px solid var(--accent-color);
  z-index: 2;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}
.text-card.selected-card .timeline-node {
  background-color: var(--accent-color);
  transform: scale(1.2);
}
/* --------------------------------------------------- */
/* CARD INNER ELEMENTS */
/* --------------------------------------------------- */
/* Card Header */
.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  flex-wrap: wrap;
}
.card-title-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1 1 150px;
  min-width: 0;
}
.card-title {
  font-size: var(--title-size);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.2px;
}
.card-subtitle {
  font-size: 11px;
  color: #64748b;
  font-weight: 500;
}
.text-viz-root.theme-dark-bg .card-subtitle {
  color: #94a3b8;
}
.card-subtitle-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin-top: 2px;
  flex-wrap: wrap;
}
.badge-subtitle-inline {
  padding: 2px 6px !important;
  border-radius: 4px !important;
}
/* Dynamic Metric Badge */
.card-metric-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px;
  background-color: rgba(59, 130, 246, 0.08);
  border: 1px solid rgba(59, 130, 246, 0.15);
  color: var(--accent-color);
  white-space: nowrap;
}
.text-viz-root.theme-dark-bg .card-metric-badge {
  background-color: rgba(59, 130, 246, 0.15);
}
/* Body Text Viewport (Pre-wrap support) */
.card-body-viewport {
  font-size: var(--body-size);
  line-height: 1.5;
  white-space: pre-wrap;
  word-wrap: break-word;
  overflow-wrap: break-word;
  scrollbar-width: thin;
  padding-right: 4px;
}
.card-body-viewport::-webkit-scrollbar {
  width: 4px;
}
.card-body-viewport::-webkit-scrollbar-thumb {
  background-color: rgba(148, 163, 184, 0.3);
  border-radius: 4px;
}
/* Card Footer */
.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: auto;
  padding-top: 4px;
}
/* Category Pill Tag */
.card-tag-pill {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 2px 8px;
  border-radius: 10px;
  background-color: #cbd5e1;
  color: #334155;
  white-space: nowrap;
}
.text-viz-root.theme-dark-bg .card-tag-pill {
  background-color: #475569;
  color: #f1f5f9;
}
/* Truncation / Expand button styling */
.read-more-trigger {
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-color);
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  outline: none;
  margin-top: 4px;
  text-align: left;
}
.read-more-trigger:hover {
  text-decoration: underline;
}
/* Empty State / Schema Errors screen */
.viz-error-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
  height: 100%;
  width: 100%;
}
.viz-error-title {
  font-size: 16px;
  font-weight: 700;
  color: #ef4444;
  margin-bottom: 8px;
}
.viz-error-desc {
  font-size: 12px;
  color: #64748b;
  max-width: 420px;
  line-height: 1.5;
}
/* Layout D: Horizontal Scroll Feed Layout */
.text-horizontal-container {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: var(--grid-gap);
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 16px;
  scroll-snap-type: x proximity;
  scrollbar-width: thin;
}
.text-horizontal-container::-webkit-scrollbar {
  height: 6px;
}
.text-horizontal-container::-webkit-scrollbar-thumb {
  background-color: rgba(148, 163, 184, 0.3);
  border-radius: 4px;
}
.horizontal-feed-card {
  flex: 0 0 320px;
  max-width: 380px;
  scroll-snap-align: start;
  min-height: 220px;
  display: flex;
  flex-direction: column;
}
